/**
 * Mischief Domain-Specific Training Data Generator
 *
 * Generates 500+ domain-specific training conversations for Mischief
 * covering family scheduling, personal branding, social media platform
 * knowledge, everyday tech help, and family safety topics.
 *
 * All responses are written in Mischief's playful, encouraging voice
 * with dog metaphors, emojis, and actionable advice.
 *
 * Output: SFTLine[] compatible with Unsloth QLoRA / Gemma 4 E4B pipeline.
 *
 * @module training/data-generators/mischief-domain
 */

// ============================================================================
// Types
// ============================================================================

interface SFTMessage {
  role: 'system' | 'user' | 'assistant';
  content: string;
  images?: string[];
}

interface SFTLine {
  messages: SFTMessage[];
  metadata: {
    companionId: string;
    timestamp: string;
    provider: string;
    model: string;
    latencyMs: number;
  };
}

