// ============================================================================
// Generator
// ============================================================================

function makeSFTLine(user: string, assistant: string, index: number): SFTLine {
  return {
    messages: [
      { role: 'system', content: SYSTEM_PROMPT },
      { role: 'user', content: user },
      { role: 'assistant', content: assistant },
    ],
    metadata: {
      companionId: COMPANION_ID,
      timestamp: new Date(Date.now() + index * 1000).toISOString(),
      provider: 'synthetic',
      model: 'mischief-domain-generator',
      latencyMs: 0,
    },
  };
}

/**
 * Generate 540+ domain-specific Mischief training examples covering
 * family scheduling, personal branding, social media platforms,
 * everyday tech help, and family safety.
 */
export async function generate(): Promise<SFTLine[]> {
  const allConversations: Array<{ user: string; assistant: string }> = [
    ...FAMILY_SCHEDULING,
    ...PERSONAL_BRANDING,
    ...SOCIAL_MEDIA_PLATFORMS,
    ...TECH_HELP,
    ...FAMILY_SAFETY,
    ...generateDomainVariations(),
  ];

  const lines: SFTLine[] = allConversations.map((conv, i) =>
    makeSFTLine(conv.user, conv.assistant, i)
  );

  // Pad with cross-domain combinations if needed
  let idx = lines.length;
  while (lines.length < SAMPLE_COUNT) {
    const a = allConversations[idx % allConversations.length]!;
    const b = allConversations[(idx * 3 + 7) % allConversations.length]!;

    const combined = `${a.user} Oh, and also: ${b.user.toLowerCase()}`;
    const response = `${a.assistant}\n\n---\n\nAs for your other question — great timing! ${b.assistant.split('\n').slice(0, 5).join('\n')}\n\n...but that\'s a big topic! Let me know if you want the full breakdown. One thing at a time! You\'ve got this!`;

    lines.push(makeSFTLine(combined, response, idx));
    idx++;
  }

  return lines;
}

export default { generate, SAMPLE_COUNT };
